const { createApp, ref, onMounted, onUnmounted } = Vue

// 这就是一个 Composable：封装了鼠标追踪的有状态逻辑
function useMouse() {
  const x = ref(0)
  const y = ref(0)

  function update(e) {
    x.value = e.clientX
    y.value = e.clientY
  }

  onMounted(() => window.addEventListener('mousemove', update))
  onUnmounted(() => window.removeEventListener('mousemove', update))

  return { x, y }
}

createApp({
  setup() {
    // 一行调用，拿到响应式鼠标坐标
    const { x, y } = useMouse()
    return { x, y }
  }
}).mount('#cpsdemo')

