const { createApp, ref, computed, watch } = Vue

createApp({
  setup() {
    const text = ref('')

    // 尝试从 localStorage 恢复数据
    const saved = localStorage.getItem('vue3-todos')
    const todos = ref(saved ? JSON.parse(saved) : [
      { text: '学会 Vue3 声明式渲染', done: true },
      { text: '掌握 ref 和 reactive', done: true },
      { text: '理解组件通信三剑客', done: false },
      { text: '用 Composables 封装逻辑', done: false }
    ])

    const doneCount = computed(() => todos.value.filter(t => t.done).length)

    function add() {
      if (text.value.trim()) {
        todos.value.push({ text: text.value.trim(), done: false })
        text.value = ''
      }
    }

    function remove(i) { todos.value.splice(i, 1) }
    function clear() {
      const remaining = todos.value.filter(t => !t.done)
      todos.value.length = 0
      todos.value.push(...remaining)
    }

    // 自动保存到 localStorage
    watch(todos, (val) => {
      localStorage.setItem('vue3-todos', JSON.stringify(val))
    }, { deep: true })

    return { text, todos, doneCount, add, remove, clear }
  }
}).mount('#todoapp')

